import React, { useEffect, useState } from 'react';
import cartService from '../../services/cartService';
import './Cart.css';

const Cart = () => {
    const [cart, setCart] = useState({ items: [], total: 0 });
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    // Demo products for better UX
    const demoProducts = [
        { id: '1', name: 'Wireless Headphones', price: 89.99, image: '🎧' },
        { id: '2', name: 'Smart Watch', price: 199.99, image: '⌚' },
        { id: '3', name: 'Laptop Stand', price: 49.99, image: '💻' },
        { id: '4', name: 'Coffee Mug', price: 19.99, image: '☕' }
    ];

    useEffect(() => {
        loadCart();
    }, []);

    const loadCart = async () => {
        try {
            setLoading(true);
            const response = await cartService.getCart();
            setCart(response.data);
        } catch (error) {
            console.error('Error fetching cart:', error);
            setError('Failed to load cart');
            setCart({ items: [], total: 0 });
        } finally {
            setLoading(false);
        }
    };

    const handleUpdate = async (productId, quantity) => {
        try {
            const response = await cartService.updateCartItem(productId, quantity);
            setCart(response.data);
        } catch (error) {
            console.error('Error updating cart:', error);
            setError('Failed to update cart');
        }
    };

    const handleAddToCart = async (product) => {
        try {
            const response = await cartService.addToCart(product.id, 1);
            setCart(response.data);
            setError(null);
        } catch (error) {
            console.error('Error adding to cart:', error);
            setError('Failed to add item to cart');
        }
    };

    const calculateTotal = () => {
        return cart.items.reduce((total, item) => total + (item.price * item.quantity), 0);
    };

    if (loading) {
        return (
            <div className="cart-loading">
                <div className="spinner"></div>
                <p>Loading your shopping cart...</p>
            </div>
        );
    }

    return (
        <div className="cart-container">
            <h2>
                <span className="bengali-text">কিনবা</span>
                <span className="question-mark">?</span> Shopping Cart
            </h2>

            {error && <div className="error-message">{error}</div>}

            {cart.items && cart.items.length > 0 ? (
                <>
                    <div className="cart-items">
                        {cart.items.map((item, index) => (
                            <div key={index} className="cart-item">
                                <div className="item-details">
                                    <h4>{item.productName || `Product ${item.productId}`}</h4>
                                    <p>${item.price || 29.99}</p>
                                </div>
                                <div className="item-actions">
                                    <span className="quantity">Qty: {item.quantity}</span>
                                    <button 
                                        className="btn btn-secondary"
                                        onClick={() => handleUpdate(item.productId, Math.max(1, item.quantity - 1))}
                                    >
                                        ➖
                                    </button>
                                    <button 
                                        className="btn btn-primary"
                                        onClick={() => handleUpdate(item.productId, item.quantity + 1)}
                                    >
                                        ➕
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>

                    <div className="cart-summary">
                        <div className="summary-row">
                            <span>Subtotal:</span>
                            <span>${calculateTotal().toFixed(2)}</span>
                        </div>
                        <div className="summary-row">
                            <span>Shipping:</span>
                            <span>Free</span>
                        </div>
                        <div className="summary-row">
                            <span>Total:</span>
                            <span>${calculateTotal().toFixed(2)}</span>
                        </div>
                    </div>

                    <div className="cart-total">
                        <h3>Total: ${calculateTotal().toFixed(2)}</h3>
                        <button className="btn btn-success" style={{ marginTop: '1rem' }}>
                            🛒 Proceed to Checkout
                        </button>
                    </div>
                </>
            ) : (
                <div className="empty-cart">
                    <h3>
                        <span className="bengali-text">কিনবা</span>
                        <span className="question-mark">?</span> Cart is Empty
                    </h3>
                    <p>Add some amazing products to get started!</p>

                    <div className="demo-products">
                        {demoProducts.map((product) => (
                            <div key={product.id} className="demo-product" onClick={() => handleAddToCart(product)}>
                                <div style={{ fontSize: '3rem', marginBottom: '1rem' }}>{product.image}</div>
                                <h4>{product.name}</h4>
                                <p>${product.price}</p>
                                <button className="btn btn-primary">
                                    ➕ Add to Cart
                                </button>
                            </div>
                        ))}
                    </div>
                </div>
            )}
        </div>
    );
};

export default Cart;
